import React, { useState } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { Home, Menu, X, LogOut, User, LayoutDashboard, ChevronDown } from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import './Navbar.css';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [menuOpen, setMenuOpen] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const handleLogout = () => {
    logout();
    navigate('/');
    setDropdownOpen(false);
  };

  const dashboardPath =
    user?.role === 'admin' ? '/admin' :
    user?.role === 'agent' ? '/agent' : '/client';

  const isActive = (path) => location.pathname === path;

  return (
    <nav className="navbar">
      <div className="container navbar-inner">
        <Link to="/" className="navbar-brand">
          <Home size={22} />
          <span>Prop<strong>Connect</strong></span>
        </Link>

        <div className={`navbar-links ${menuOpen ? 'open' : ''}`}>
          <Link to="/listings" className={isActive('/listings') ? 'active' : ''} onClick={() => setMenuOpen(false)}>Browse Listings</Link>
          {!user && (
            <>
              <Link to="/login" className={`btn btn-outline btn-sm ${isActive('/login') ? 'active' : ''}`} onClick={() => setMenuOpen(false)}>Sign In</Link>
              <Link to="/register" className={`btn btn-accent btn-sm`} onClick={() => setMenuOpen(false)}>Register</Link>
            </>
          )}
          {user && (
            <div className="user-menu">
              <button className="user-trigger" onClick={() => setDropdownOpen(!dropdownOpen)}>
                <div className="user-avatar">{user.name?.charAt(0)}</div>
                <span>{user.name}</span>
                <ChevronDown size={14} />
              </button>
              {dropdownOpen && (
                <div className="user-dropdown">
                  <Link to={dashboardPath} onClick={() => { setDropdownOpen(false); setMenuOpen(false); }}>
                    <LayoutDashboard size={15} /> Dashboard
                  </Link>
                  <Link to="/profile" onClick={() => { setDropdownOpen(false); setMenuOpen(false); }}>
                    <User size={15} /> Profile
                  </Link>
                  <button onClick={handleLogout} className="logout-btn">
                    <LogOut size={15} /> Sign Out
                  </button>
                </div>
              )}
            </div>
          )}
        </div>

        <button className="hamburger" onClick={() => setMenuOpen(!menuOpen)}>
          {menuOpen ? <X size={22} /> : <Menu size={22} />}
        </button>
      </div>
    </nav>
  );
}
